//
// Generated by tools/starsiege_to_tribes.py.
// A Herc walks because Tribes players pick their animation from measured
// root motion; vehicles never animate. See the tool docstring.
//
// The shape has had the Tribes player utility nodes injected
// (tools/inject_player_nodes.py): "dummyalways root",
// "dummyalways chasecam", and per detail size "dummy hand<N>",
// "dummy unused<N>", "dummy midback<N>", "dummy lowback<N>",
// "dummy eye<N>" -- the names Player::initResources resolves.
//
// Collision box + chase-camera height are sized to the model's
// measured bind-pose extents (a Herc is ~7m tall vs a trooper ~2m).
// Skins are 24-bit true-color BMP so the engine does not recolor them
// through its world palette. Install with the tool's --install step.
//--------------------------------------------------------------------------

PlayerData HercCabasl
{
   className = "Armor";
   shapeFile = "ca_basl";
   //  no damage skins / flame / shield shapes: those are Tribes-player
   //  assets and a Herc has none. Leaving them unset is safe.
   validateShape = false;

