//--- wear it -----------------------------------------------------------
// IMPORTANT: this datablock must be declared at SERVER STARTUP, not from
// the console. createServer() (base scripts.vol server.cs) execs the
// armor/item/etc. files and THEN calls preloadServerDataBlocks(); a
// PlayerData declared after that is never registered, so Player::setArmor
// silently reverts (verified: a console-exec'd datablock on the stock
// larmor shape fails while startup-declared larmor works).
//
// The tool's --install step makes a loose base\armordata.cs (stock copy +
// exec("herccabasl.cs")), which createServer runs before preload. After
// installing, RESTART the listen server, then:
//
//     beHercCabasl();
//
// On a listen server the console is the server console, so Player::setArmor
// works directly -- $ServerCheats only gates the remoteSetArmor path that
// remote clients use.
//
// Spawn in as a normal player FIRST -- there has to be a control object to
// re-skin. GameBase::setDatFileName reloads the datablock and reverts to
// the previous one if the new shape fails to load, so a bad port is not
// fatal -- watch the console for the revert.

// Find the SERVER-side player object.
//
// Player::setArmor resolves its argument with findPlayerObject(), which
// searches the SERVER manager (sg.manager, FearPlugin.cpp:219).
// getLocalObject() returns the CLIENT PSC's control object -- a ghost with
// a different id -- so passing it yields a non-zero id that findPlayerObject
// still cannot resolve, and setArmor/getArmor just answer "False".
// Client::getControlObject(id) goes through sg.playerManager and returns the
// real server object, so scan the client ids. They start at 2048, not 0
// (PlayerManager: clientId = readInt(7) + 2048); a listen host is 2048.
function findServerPlayer()
{
   for (%i = 2048; %i < 2176; %i++) {
      %o = Client::getControlObject(%i);
      if (%o > 0 && Player::getClient(%o) > 0)
         return %o;
   }
   return -1;
}

function beHercCabasl()
{
   %p = findServerPlayer();
   if (%p <= 0) {
      echo("beHercCabasl: no server-side player found -- spawn into the world first.");
      echo("  (getLocalObject() = " @ getLocalObject() @ " is the client ghost, not usable here)");
      return;
   }
   echo("player object " @ %p @ " (client " @ Player::getClient(%p) @ "), armor was " @ Player::getArmor(%p));
   Player::setArmor(%p, "HercCabasl");
   echo("armor is now: " @ Player::getArmor(%p));
}

// back to a stock trooper
function beHercCabasl_off()
{
   %p = findServerPlayer();
   if (%p > 0) {
      Player::setArmor(%p, "larmor");
      echo("armor is now: " @ Player::getArmor(%p));
   }
}
